import React, { useEffect, useState } from "react";
import axios from "axios";
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Paper from '@mui/material/Paper';

export default function Books() {
    const [books, setBooks] = useState([]); // State to store book data

    useEffect(() => {
        loadBooks(); // Load books when the component mounts
    }, []);

    const loadBooks = async () => {
        try {
            const result = await axios.get("http://localhost:8081/books");
            setBooks(result.data); // Set the fetched books to state
        } catch (error) {
            console.error("Error loading books:", error);
        }
    };

    return (
        <TableContainer component={Paper}>
            <Table sx={{ minWidth: 650 }} aria-label="books table">
                <TableHead>
                    <TableRow>
                        <TableCell>Title</TableCell>
                        <TableCell align="left">Author</TableCell>
                        <TableCell align="left">ISBN</TableCell>
                        <TableCell align="right">Quantity</TableCell>
                        <TableCell align="left">Added At</TableCell>
                    </TableRow>
                </TableHead>
                <TableBody>
                    {books.length > 0 ? (
                        books.map((book) => (
                            <TableRow key={book.id}>
                                <TableCell>{book.title}</TableCell>
                                <TableCell align="left">{book.author}</TableCell>
                                <TableCell align="left">{book.isbn}</TableCell>
                                <TableCell align="right">{book.quantity}</TableCell>
                                <TableCell align="left">{new Date(book.addedAt).toLocaleString()}</TableCell>
                                <TableCell align="left">{new Date(book.addedAt).toLocaleString()}</TableCell>
                            </TableRow>
                        ))
                    ) : (
                        <TableRow>
                            <TableCell colSpan={5} align="center">
                                No books available
                            </TableCell>
                        </TableRow>
                    )}
                </TableBody>
            </Table>
        </TableContainer>
    );
}
